window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:ginecologia-cancer-de-colo-uterino"]={"block":"anki:ginecologia-cancer-de-colo-uterino","label":"Anki · Câncer de Colo Uterino","count":100,"questions":[{"id":"anki-ginecologia-cancer-de-colo-uterino-4e9696cdc9382c94","number":"0201r","sourceNumber":"0201r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 25 anos chega à emergência ginecológica, com quadro de sangramento genital com odor desagradável há vários dias. Informa sangramento durante atividade sexual. O exame ginecológico revela tumoração cervical de 06 cm, restrita ao colo uterino. Vagina e paramétrios estão livres. Não possui exames complementares. Considerando o quadro acima, no momento, qual o provável estadiamento até o momento e tratamento?","options":{"A":"Ib3, radioterapia","B":"Ib1, radioterapia","C":"IIa1, cirurgia Piver tipo 5","D":"IIIa, radioterapia","E":"Ia2, cirurgia Piver tipo 3"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963373","ankiGuid":"B=j1P)A.L^"},{"id":"anki-ginecologia-cancer-de-colo-uterino-eb5b51556982ad11","number":"0202r","sourceNumber":"0202r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 47 anos de idade, deu entrada no PS com crise hipertensiva. Exames complementares revelaram ureia 60mg/dL e creatinina de 7 mg/dL, US de vias urinárias com dilatação ureteral bilateral acentuada. Refere diagnóstico recente de carcinoma epidermóide de colo de útero, ainda sem tratamento.\nA conduta mais adequada do ponto de vista oncológico é:","options":{"A":"radioterapia associada a quimioterapia sensibilizadora","B":"cirurgia de Werthein Meigs","C":"traquelectomia radical e parametrectomia","D":"imunoterapia com pembrolizumabe (anti PD-L1)"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963374","ankiGuid":"P[?8qn]4/t"},{"id":"anki-ginecologia-cancer-de-colo-uterino-448778c23c128792","number":"0203r","sourceNumber":"0203r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 49 anos foi submetida à histerectomia devido a dor no baixo ventre e identificação de massa pélvica. Exame macroscópico da peça cirúrgica:\n\nAs características macroscópicas da imagem favorecem o diagnóstico de:","options":{"A":"doença inflamatória pélvica com cicatrizes extensas","B":"teratoma adulto benigno com áreas de necrose","C":"cistos de Naboth com infecções recorrentes","D":"câncer avançado do colo do útero"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":["question_bank/media/ginecologia-cancer-de-colo-uterino/paste-04b2dad8a2a424fa02f61d5a94d47f4d29231d80.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963375","ankiGuid":"fvV+6JXnZb"},{"id":"anki-ginecologia-cancer-de-colo-uterino-44eabc8c9ac084cb","number":"0204r","sourceNumber":"0204r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 42 anos, casada e com 3 filhos, em uso de DIU de cobre, veio à consulta com queixas de sangramento intermitente. Informou ter realizado a última revisão ginecológica há 5 anos (em atraso devido à pandemia). Ao exame físico, a pressão arterial era de 130/85 mmHg, o peso, de 60 kg, e a altura, de 168 cm; mamas, abdômen e vulva não apresentaram particularidades. O exame especular indicou colo com lesão de aspecto tumoral, medindo 1 cm. Foi realizada [procedimento]. Com base no resultado, [...], foi indicada [...]. Qual alternativa preenche correta e respectivamente as lacunas?","options":{"A":"coleta de material para exame citopatológico – lesão intraepitelial de alto grau – conização","B":"colposcopia – lesão sugestiva de câncer invasor – histerectomia extrafascial","C":"biópsia – carcinoma invasor – realização de estadiamento","D":"biópsia – adenocarcinoma invasor – histerectomia extrafascial"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963376","ankiGuid":"kd(.3aS^l8"},{"id":"anki-ginecologia-cancer-de-colo-uterino-4e5aab482cfac50a","number":"0205r","sourceNumber":"0205r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 38 anos realizou biópsia de colo uterino que evidenciou carcinoma escamoso. Ao examiná-la, verifica-se uma lesão de 6cm limitada ao colo, não acometendo a vagina. A ressonância magnética de pelve não evidenciou comprometimento parametrial ou linfonodal. A indicação terapêutica é de:","options":{"A":"laparotomia exploradora","B":"histerectomia radical","C":"conização clássica","D":"radioquimioterapia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963377","ankiGuid":"K!jXm:F8=C"},{"id":"anki-ginecologia-cancer-de-colo-uterino-69ed39599fe03bdc","number":"0206r","sourceNumber":"0206r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Com relação ao estadiamento do câncer de colo uterino, assinale as alternativas abaixo. I. – Recomenda-se, se disponível, tomografia computadorizada por emissão de pósitrons (PET-TC) nas pacientes em estádio > IB2, principalmente na suspeita de envolvimento linfonodal. II - O exame de toque retal se mostra superior ao estudo por ressonância na avaliação dos paramétrios. III - Naquelas que apresentem sinais sugestivos de invasão de bexiga ou reto pelos exames de imagem, devem-se realizar cistoscopia e retossigmoidoscopia, respectivamente. Sobre esta situação selecione a opção correta.","options":{"A":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","B":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","C":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","D":"As afirmativas I, II e III são verdadeiras.","E":"As afirmativas I, II e III são falsas."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963378","ankiGuid":"beU!Dz52qh"},{"id":"anki-ginecologia-cancer-de-colo-uterino-464d008fde9b34f6","number":"0207r","sourceNumber":"0207r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 30 anos, G4P4, todos os partos vaginais. Procurou o ambulatório de ginecologia com queixa de sangramento durante o ato sexual e secreção vaginal com odor desagradável. O quadro teve início há quatro meses. Durante o exame, foi encontrado um tumor restrito ao colo uterino, com 3,0 cm no maior diâmetro, sem comprometimento parametrial. Exames laboratoriais normais. A propedêutica de imagem revelou tumoração restrita à região cervical sem demais alterações. De acordo com o quadro acima, assinale a alternativa correspondente ao estadiamento e à conduta mais adequada.","options":{"A":"Ia1/conização","B":"Ib1/traquelectomia","C":"Ib2/Wertheim-Meigs","D":"Ib3/radioterapia","E":"Ia2/CAF"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963379","ankiGuid":"bYqhqmc$CL"},{"id":"anki-ginecologia-cancer-de-colo-uterino-d8851700887aad78","number":"0208r","sourceNumber":"0208r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Um estudante de medicina encontra-se ansioso, pois fará a prova final de anatomia do semestre e precisa acertar todas as questões. O tema escolhido pelo professor foi anatomia da cavidade pélvica feminina. Com base nesse caso hipotético, é correto afirmar que, para atingir seu objetivo, o estudante deverá saber que","options":{"A":"os vasos linfáticos do corpo e do colo do útero drenam para os linfonodos ilíacos internos e externos.","B":"as tubas uterinas são irrigadas exclusivamente pelas artérias ováricas.","C":"o istmo é a porção mais larga da tuba uterina.","D":"o eixo longo do útero normalmente é inclinado para a frente, sobre o eixo longo da vagina, posição conhecida como anteflexão.","E":"a artéria uterina cruza o ureter e alcança o colo uterino no nível de seu óstio externo."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963380","ankiGuid":"wnV~31H.rF"},{"id":"anki-ginecologia-cancer-de-colo-uterino-d8e3ffc2862ae618","number":"0209r","sourceNumber":"0209r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 46 anos apresenta sangramento vaginal em grande quantidade há 3 dias. Relata irregularidade menstrual com presença de sangramento intermenstruo recorrente, de moderada quantidade, há 2 anos, além de sinusorragia e secreção vaginal de forte odor de longa data. AP: G5P3A2C2. Exame especular: moderada quantidade de sangramento vaginal, lesão exofítica friável com aproximadamente 2 cm de diâmetro. Toque vaginal: lesão nodular endurecida, confinada a cérvix uterina, útero e anexos de difícil delimitação, fundos de saco vaginais livres. Toque retal: paramétrios livres. Exames laboratoriais: Hb 6,8 g/dL, Ht 27%, ureia 32 mg/dL, creatinina 0,8 mg/dL. A conduta correta é:","options":{"A":"citologia oncótica cervical, conização e radioterapia.","B":"citologia oncótica cervical, colposcopia e abordagem cirúrgica.","C":"colposcopia, biópsia da lesão, radioterapia e quimioterapia.","D":"biópsia da lesão, tomografia computadorizada e abordagem cirúrgica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963381","ankiGuid":"waB%3R9~Si"},{"id":"anki-ginecologia-cancer-de-colo-uterino-478ca09032948a49","number":"0210r","sourceNumber":"0210r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 26 anos vem à consulta para rastreamento do câncer do colo do útero. Refere nunca ter realizado exame ginecológico antes. Ao exame, identifica-se massa friável exofítica de 3cm no colo do útero, com ulceração. Qual o próximo passo para o diagnóstico da lesão?","options":{"A":"Exame citopatológico do colo uterino.","B":"Biópsia incisional da lesão exofítica.","C":"Histerectomia simples vaginal.","D":"Conização do colo do útero com alça de alta frequência."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963382","ankiGuid":"xK*A_iCD+A"},{"id":"anki-ginecologia-cancer-de-colo-uterino-5673e9b33836148d","number":"0211r","sourceNumber":"0211r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Entre os tipos de cânceres que acomete a mulher, o terceiro mais frequente é o câncer de colo de útero, e o tipo mais comum é o carcinoma escamoso ou espinocelular. Qual a via de propagação mais frequente dessa neoplasia?","options":{"A":"Linfática.","B":"Por contiguidade.","C":"Venosa.","D":"Arterial."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963383","ankiGuid":"mi{QQYk=&H"},{"id":"anki-ginecologia-cancer-de-colo-uterino-247f2f424827d3a1","number":"0212r","sourceNumber":"0212r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 38 anos teve confirmado o diagnóstico de adenocarcinoma de colo de útero. Consultou com ginecologista oncológico para receber informações a respeito de seu diagnóstico e definir o tratamento. Assinale a assertiva correta sobre o câncer de colo de útero.","options":{"A":"As neoplasias intraepiteliais cervicais de alto grau apresentam percentual significativo de progressão para neoplasias invasoras ao longo do tempo, justificando-se, assim, o tratamento dessas lesões quando diagnosticadas.","B":"A disseminação é principalmente hematogênica.","C":"O estadiamento, segundo a FIGO, envolve principalmente a utilização de ressonância magnética com contraste para identificar o crescimento local do tumor.","D":"O diagnóstico deve estar errado, pois a paciente não se encontra na faixa etária considerada de risco para câncer de colo de útero."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963384","ankiGuid":"p7y0+eY9]0"},{"id":"anki-ginecologia-cancer-de-colo-uterino-924cb8e1934db480","number":"0213r","sourceNumber":"0213r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O câncer de colo uterino e as suas lesões precursoras ainda são incidentes no nosso meio, e são objeto de várias campanhas governamentais dirigidas à saúde da mulher. Sobre essa patologia, assinale a alternativa correta.","options":{"A":"O HPV 16 é o mais encontrado nas neoplasias intraepiteliais (NIC) 2 e 3 e em quase metade das mulheres com câncer de colo.","B":"Mesmo nos tumores evidentes clinicamente, a colposcopia do colo uterino está indicada para melhorar a acurácia diagnóstica.","C":"O tratamento cirúrgico radical pode ser indicado até estádios IB.","D":"O adenocarcinoma tem diminuído sua proporção em relação ao carcinoma de células escamosas, e seu pico de incidência é na quinta década de vida."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963385","ankiGuid":"idp<&H^>fD"},{"id":"anki-ginecologia-cancer-de-colo-uterino-fb20282a6bfc8da1","number":"0214r","sourceNumber":"0214r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 48 anos de idade, foi admitida no PS com diagnóstico de tromboembolismo pulmonar agudo. Apresenta oligúria e sangramento vaginal em moderada quantidade. Exame físico: presença de massa no colo do útero, medindo 6 cm, friável, necrótica, sangrante, com forte odor pútrido, ocupando fórnices vaginais. Exames laboratoriais: Hb 5,4 g/dL; Ht 12,2%; Ureia 245 mg/dL; Creatinina 7,5 mg/dL. US de rins e vias urinárias: dilatação ureteral bilateral acentuada. Qual é a conduta mais adequada, após a compensação clínica?","options":{"A":"Derivação urinária com duplo J ou nefrostomia; cirurgia de Wertheim Meigs.","B":"Derivação urinária com duplo J ou nefrostomia, radio e quimioterapia.","C":"Histerectomia total abdominal com salpingectomia bilateral.","D":"Encaminhamento para ambulatório de cuidados paliativos."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963386","ankiGuid":"DKOXOcYcVv"},{"id":"anki-ginecologia-cancer-de-colo-uterino-185e0e5c23def5b3","number":"0215r","sourceNumber":"0215r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Nas pacientes diagnosticadas com carcinoma do colo uterino, a opção de tratamento inicial mais adequada varia de acordo com o estadiamento clínico. Sobre esta situação selecione a opção correta. I - Histerectomia total é o tratamento recomendado para pacientes que apresentam tumor com invasão de até 3 mm, sem invasão linfática e vascular, e sem dissecção linfonodal, pois o risco de metástases linfonodais é < 1%. II - Para tumores com invasão acima de 3 mm ou com invasão linfática e vascular, o tratamento de rotina deve ser a histerectomia radical associada à técnica do linfonodo sentinela ou linfadenectomia pélvica bilateral, pois o risco de metástases linfonodais é de cerca de 5%. III - A conização pode ser uma opção para pacientes que desejam manter a fertilidade, mas que apresentam tumores com invasão menor que 3 mm, sem invasão linfática e vascular, e margens livres.","options":{"A":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","B":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","C":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","D":"As afirmativas I, II e III são verdadeiras.","E":"As afirmativas I, II e III são falsas."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963387","ankiGuid":"inJ^n5RU:Y"},{"id":"anki-ginecologia-cancer-de-colo-uterino-0f7d8ad1bfb2fec1","number":"0216r","sourceNumber":"0216r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Qual o tipo histológico mais comum no câncer do colo do útero?","options":{"A":"Tumores adenoescamosos","B":"Carcinoma de células escamosas","C":"Carcinoma basocelular","D":"Rabdomiossarcoma","E":"Adenocarcinoma"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963388","ankiGuid":"FvU6LTrxa1"},{"id":"anki-ginecologia-cancer-de-colo-uterino-4a86c6675dd77eab","number":"0217r","sourceNumber":"0217r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 35 anos apresenta diagnóstico de câncer do colo do útero com estadiamento IB1 (International Federation of Gynecology and Obstetrics − FIGO). Para investigação de acometimento linfonoidal, dentre as opções abaixo, a mais indicada para este caso é","options":{"A":"tomografia por emissão de pósitrons combinada com tomografia computadorizada.","B":"ressonância magnética nuclear da pelve.","C":"ultrassonografia transretal.","D":"tomografia computadorizada de abdômen e pelve."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963389","ankiGuid":"CJ;n@*$J4N"},{"id":"anki-ginecologia-cancer-de-colo-uterino-51b1fe057072d4bc","number":"0218r","sourceNumber":"0218r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"De acordo com estadiamento do câncer cervical da FIGO (Federação Internacional de Ginecologia e Obstetrícia) 2018, é correto afirmar:","options":{"A":"Estadio IA2: profundidade da invasão menor que 3 mm.","B":"Estadio IIA1: carcinoma invasor com dimensões acima de 4 cm, envolvendo 1/3 superior de vagina sem envolvimento parametrial.","C":"Estadio IIIC1: metástases em linfonodos pélvicos somente.","D":"Estadio IIIB: carcinoma envolvendo 1/3 inferior de vagina, mas não parede pélvica.","E":"Estadio IV B: disseminação para órgãos pélvicos adjacentes."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963390","ankiGuid":"j<;H?Vf~n)"},{"id":"anki-ginecologia-cancer-de-colo-uterino-130ea140e8332a74","number":"0219r","sourceNumber":"0219r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 36 anos, casada, G3 P3(N)A0, refere sinusorragia há 6 meses, sendo que nos últimos 2 meses tem evoluído com sangramento intermitente entre as menstruações. Ao exame físico lesão vegetante de colo, aparentemente restrita ao colo e sem envolvimento de paramétrios ou vagina. A Biópsia dirigida revelou tratar-se de carcinoma epidermoide de colo uterino grau 2. Assim sendo, de acordo com o estadiamento clínico, a idade e diagnóstico, a melhor conduta deve ser:","options":{"A":"Radioterapia pélvica com quimioterapia sensibilizante, tendo em vista a gravidade da doença.","B":"Histerectomia total com salpingectomia e preservação de ovários, tendo em vista se tratar de paciente jovem.","C":"Histerectomia total ampliada (Wertheim Meigs) incluindo salpingooforectomia bilateral, tendo em vista a gravidade da doença.","D":"Histerectomia Total Ampliada (Wertheim Meigs) com preservação de ovários, seguida de Radioterapia pélvica tendo em vista a gravidade da doença.","E":"Histerectomia Total Ampliada (Wertheim Meigs) com possibilidade de preservação de ovários, tendo em vista a idade da paciente."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963391","ankiGuid":"wG#,9-i^S:"},{"id":"anki-ginecologia-cancer-de-colo-uterino-1d27b144dd5cf60a","number":"0220r","sourceNumber":"0220r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"P.R.S; 53 anos, prole constituída, citologia oncótica, apresentando lesão intraepitelial escamosa de alto grau e colposcopia alterada. Realizada biópsia de colo uterino. Resultado do anatomopatológico: suspeita de microinvasão. Indicada conização, e o resultado histopatológico da peça foi carcinoma escamoso de 15 mm no maior diâmetro. Assinale a alternativa que apresenta a conduta correta para o caso.","options":{"A":"Histerectomia radical com linfadenectomia pélvica.","B":"Traquelectomia.","C":"Quimioterapia neoadjuvante.","D":"Radioterapia.","E":"Exenteração pélvica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963392","ankiGuid":"i0IeD.udrc"},{"id":"anki-ginecologia-cancer-de-colo-uterino-ff6fcaec4c6907f7","number":"0221r","sourceNumber":"0221r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Existem muitos fatores de risco para o câncer do colo do útero: primeira relação sexual em idade jovem (menos de 16 anos), múltiplos parceiros sexuais, tabagismo, raça, paridade elevada, baixa condição socioeconômica e imunossupressão crônica. A respeito do câncer de colo uterino, assinale a alternativa CORRETA:","options":{"A":"A profundidade da lesão é um importante preditor de metástase para linfonodos pélvicos","B":"A taxa de falso-negativo da colpocitologia oncótica no câncer invasor é muito baixa","C":"Dor pélvica crônica é o sintoma mais comum nas pacientes acima de 50 anos","D":"O câncer de colo de útero é uma doença de estadiamento cirúrgico"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963393","ankiGuid":"Fk}!dc}>X|"},{"id":"anki-ginecologia-cancer-de-colo-uterino-e52ebe2ca130cb11","number":"0222r","sourceNumber":"0222r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"G.L.P., 39 anos, procura serviço médico com queixa de sangramento intermitente, dor pélvica crônica, sinusiorragia, apatia. Ao exame físico geral, paciente encontra-se emagrecida e descorada. Ao exame especular, observa-se tumoração em colo uterino exofídica, característica de neoplasia maligna do colo uterino. A figura a seguir mostra a extensão da lesão e o estágio de acordo com a FIGO (Federação Internacional de Ginecologia e Obstetrícia).\n\nCom base nesse quadro, o estadiamento clínico e o tratamento adequado são","options":{"A":"IIA, cirurgia de Wertheim-Meigs.","B":"IIB, radioterapia.","C":"IIB, cirurgia de Wertheim-Meigs e radioterapia.","D":"IVA, quimiorradioterapia.","E":"IVB, quimioterapia."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":["question_bank/media/ginecologia-cancer-de-colo-uterino/paste-91cbd3877e1cc7d1e92c3148a072612a043feeaf.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963394","ankiGuid":"Nb)h#Fe[O!"},{"id":"anki-ginecologia-cancer-de-colo-uterino-a9232bb4880b9079","number":"0223r","sourceNumber":"0223r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Para diagnóstico definitivo de carcinoma in situ do colo do útero, são necessários","options":{"A":"colpocitologia com lesão de alto grau e colposcopia evidenciando lesão acetobranca.","B":"colpocitologia com lesão de alto grau e colposcopia com biópsia evidenciando carcinoma in situ do colo.","C":"colpocitologia com lesão de alto grau, colposcopia com biópsia evidenciando carcinoma in situ do colo e cortes histológicos seriados de peça proveniente de cone com acometimento da membrana basal e com margens livres.","D":"colpocitologia com lesão de alto grau, colposcopia com biópsia evidenciando carcinoma in situ do colo e cortes histológicos seriados de peça proveniente de cone sem acometimento da membrana basal e sem margens livres.","E":"colpocitologia com lesão de alto grau, colposcopia com biópsia evidenciando carcinoma in situ do colo e cortes histológicos seriados de peça proveniente de cone sem acometimento da membrana basal e com margens livres."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963395","ankiGuid":"OB]lQ|^$[P"},{"id":"anki-ginecologia-cancer-de-colo-uterino-cef9db756a746a67","number":"0224r","sourceNumber":"0224r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente, 20 anos, nuligesta, foi ao ambulatório com queixa de sinusiorragia, corrimento vaginal e dor pélvica. Realizou biópsia de colo que evidenciou carcinoma escamoso estádio 1 A. Qual o tratamento indicado para essa paciente?","options":{"A":"Conização a frio","B":"Histerectomia radical com linfadenectomia pélvica","C":"Histerectomia com ooforectomia","D":"Traquelectomia"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963396","ankiGuid":"ELFOcFq=9m"},{"id":"anki-ginecologia-cancer-de-colo-uterino-871b1065ee997f79","number":"0225r","sourceNumber":"0225r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 30 anos, G5P5, todos os partos normais. Chega à emergência ginecológica com quadro de sangramento pela vagina, há uma semana. Nega corrimento genital e febre. O exame ginecológico revelou presença de tumor em colo uterino de seis centímetros de diâmetro, friável e sangrante. O tumor compromete o terço superior da vagina, no entanto não atinge paramétrios. Traz consigo exame ultrassonográfico que revela hidronefrose. De acordo com o cenário descrito acima, assinale a alternativa que melhor destaca a principal suspeita diagnóstica com o estadiamento, a propedêutica e a conduta.","options":{"A":"Neoplasia de colo IIIB, biópsia cervical, radio e quimioterapia.","B":"Neoplasia de colo IIIA, citologia oncótica, radio e quimioterapia.","C":"Neoplasia de colo IIIA, colposcopia, histerectomia ampliada.","D":"Neoplasia de colo IIB, biópsia cervical, histerectomia radical.","E":"Neoplasia de colo IIA, biópsia cervical, radio e quimioterapia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963397","ankiGuid":"yVZ;$_ZJdw"},{"id":"anki-ginecologia-cancer-de-colo-uterino-657f8dbdfe8bb7fa","number":"0226r","sourceNumber":"0226r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 40 anos de idade refere corrimento vaginal sanguinolento e odor pronunciado há cerca de 5 meses. Refere ciclos menstruais mensais regulares, porém com dificuldade de identificá-los devido ao sangramento irregular dos últimos meses. Refere vida sexual ativa, com parceiro sexual vasectomizado. Quatro partos vaginais prévios (último há 7 anos). Nega co-morbidades ou uso de medicamentos. Ao exame especular observa-se a imagem a seguir.\n\nQual é a conduta neste momento?","options":{"A":"Biópsia.","B":"Colpocitologia.","C":"Colposcopia.","D":"Pesquisa de Clamídia e Neisseria."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":["question_bank/media/ginecologia-cancer-de-colo-uterino/paste-beefc50b506e0b6f0c6b7dc76fb5806ed277982d.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963398","ankiGuid":"d2:FRzd(Up"},{"id":"anki-ginecologia-cancer-de-colo-uterino-b148b2968baf082e","number":"0227r","sourceNumber":"0227r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O câncer de colo uterino ainda é o tumor ginecológico mais comum entre as brasileiras e desenvolve-se em uma população mais jovem em relação aos outros tumores do trato genital. Sobre esse câncer, é correto afirmar:","options":{"A":"O subtipo histológico adenocarcinoma é o mais prevalente e as lesões são exofíticas.","B":"Os sintomas são precoces e específicos, principalmente em pacientes jovens.","C":"O estadiamento é clínico, entretanto, pode ser ajudado nos casos iniciais pelo cone a frio.","D":"O estadiamento IIB inclui presença de hidronefrose por compressão do ureter pelo tumor."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963399","ankiGuid":"cO_a[n`2N+"},{"id":"anki-ginecologia-cancer-de-colo-uterino-4b26c3da7be22b43","number":"0228r","sourceNumber":"0228r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 36 anos de idade foi atendida em primeira consulta com equipe de oncologia ginecológica, em abril de 2019, com queixa de sinusiorragia. Foi diagnosticada com adenocarcinoma de colo do útero, estágio clínico IIB. Indicou-se tratamento, porém a paciente não desejou realizá-lo naquele momento, retornando um ano depois, grávida (G6P4C1), com idade gestacional de 30 semanas e 3 dias, referindo dificuldade para deambular e dor no quadril à esquerda. Foram, então, identificadas metástase óssea e fratura patológica, e re-estadiada para estágio clínico IVB. Após avaliações iniciais, a paciente definiu que desejava manter a gestação. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue os itens a seguir. A paciente não possui indicação de tratamento cirúrgico para o câncer de colo do útero.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963400","ankiGuid":"M2tig)<{|r"},{"id":"anki-ginecologia-cancer-de-colo-uterino-eb43799654a520e7","number":"0229r","sourceNumber":"0229r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 36 anos de idade foi atendida em primeira consulta com equipe de oncologia ginecológica, em abril de 2019, com queixa de sinusiorragia. Foi diagnosticada com adenocarcinoma de colo do útero, estágio clínico IIB. Indicou-se tratamento, porém a paciente não desejou realizá-lo naquele momento, retornando um ano depois, grávida (G6P4C1), com idade gestacional de 30 semanas e 3 dias, referindo dificuldade para deambular e dor no quadril à esquerda. Foram, então, identificadas metástase óssea e fratura patológica, e re-estadiada para estágio clínico IVB. Após avaliações iniciais, a paciente definiu que desejava manter a gestação. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue os itens a seguir. Se indicado, o tratamento proposto será paliativo.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963401","ankiGuid":"jZbrp),t`i"},{"id":"anki-ginecologia-cancer-de-colo-uterino-9eb862ca02a80243","number":"0230r","sourceNumber":"0230r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 36 anos de idade foi atendida em primeira consulta com equipe de oncologia ginecológica, em abril de 2019, com queixa de sinusiorragia. Foi diagnosticada com adenocarcinoma de colo do útero, estágio clínico IIB. Indicou-se tratamento, porém a paciente não desejou realizá-lo naquele momento, retornando um ano depois, grávida (G6P4C1), com idade gestacional de 30 semanas e 3 dias, referindo dificuldade para deambular e dor no quadril à esquerda. Foram, então, identificadas metástase óssea e fratura patológica, e re-estadiada para estágio clínico IVB. Após avaliações iniciais, a paciente definiu que desejava manter a gestação. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue os itens a seguir. A paciente poderá realizar tratamento com quimioterapia.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963402","ankiGuid":"g*Jw75q*6K"},{"id":"anki-ginecologia-cancer-de-colo-uterino-30be0d86d36b63c3","number":"0231r","sourceNumber":"0231r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 36 anos de idade foi atendida em primeira consulta com equipe de oncologia ginecológica, em abril de 2019, com queixa de sinusiorragia. Foi diagnosticada com adenocarcinoma de colo do útero, estágio clínico IIB. Indicou-se tratamento, porém a paciente não desejou realizá-lo naquele momento, retornando um ano depois, grávida (G6P4C1), com idade gestacional de 30 semanas e 3 dias, referindo dificuldade para deambular e dor no quadril à esquerda. Foram, então, identificadas metástase óssea e fratura patológica, e re-estadiada para estágio clínico IVB. Após avaliações iniciais, a paciente definiu que desejava manter a gestação. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue os itens a seguir. A paciente não poderá realizar nenhum tipo de tratamento com radioterapia.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963403","ankiGuid":"m6@kRu9;pi"},{"id":"anki-ginecologia-cancer-de-colo-uterino-783a16bee2d62849","number":"0232r","sourceNumber":"0232r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"No Brasil o câncer de colo do útero ainda é um importante problema de saúde pública. Sobre essa doença é correto afirmar de acordo com as estimativas do INCA para 2020:","options":{"A":"A estimativa para o Brasil é de cerca de 55.000 casos, com predomínio na região norte e sudeste.","B":"Para o Paraná estima-se por volta de 5.000 casos neste ano.","C":"Estima-se para 2020 cerca de 18.000 mortes por esse câncer.","D":"Curitiba deverá ter perto de 100 casos."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963404","ankiGuid":"BZ3U.LZyGW"},{"id":"anki-ginecologia-cancer-de-colo-uterino-21b526bd189c3174","number":"0233r","sourceNumber":"0233r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Considere as assertivas abaixo sobre carcinoma epidermoide de colo uterino. I - As neoplasias intraepiteliais cervicais de alto grau apresentam percentual significativo de progressão para neoplasias invasoras, justificando-se, assim, o tratamento dessas lesões quando diagnosticadas. II - A disseminação do carcinoma de colo de útero é principalmente hematogênica para pulmão e fígado. III – O estadiamento do tumor não tem impacto na sobrevida livre de doença. Quais são as corretas?","options":{"A":"Apenas I","B":"Apenas II","C":"Apenas III","D":"Apenas I e II"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963405","ankiGuid":"NmSWu7wwdX"},{"id":"anki-ginecologia-cancer-de-colo-uterino-5f2a04f7f676714c","number":"0234r","sourceNumber":"0234r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Sobre o câncer de colo, podemos afirmar: I - os carcinomas do colo do útero são carcinomas epidermoides do tipo usual, relacionados à infecção pelo HPV; II - São variantes do carcinoma epidermoide cervical: basaloide, verrucoso, papilifero e linfoepitelioma-símile; III - Além de carcinomas epidermoides cervicais, outro tipo comum é o adenocarcinoma endocervical usual; IV - A NIC1 indica uma infecção ativa por papilomavírus humano (HPV) e é considerada lesão de baixo grau com índice muito alto de regressão espontânea. Das afirmativas acima, estão corretas:","options":{"A":"Apenas I e II.","B":"Apenas I e III.","C":"Apenas II, III e IV.","D":"Apenas III e IV.","E":"I, II, III e IV."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963406","ankiGuid":"egFBRg|L+a"},{"id":"anki-ginecologia-cancer-de-colo-uterino-c1ff5cb88202398b","number":"0235r","sourceNumber":"0235r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente, 50 anos, do sexo feminino, portadora de hipertensão arterial sistêmica há 15 anos e diabética há 20 anos, comparece em consulta com especialista. Apresenta-se com queixa de adinamia, redução de acuidade visual, palidez cutânea e edema de membros inferiores há pelo menos seis meses. Realizava acompanhamento regular no PSF, e ainda assim não alcançava bom controle pressórico e nem glicêmico. Ao exame, apresentava: PA = 160x100mmHg, mucosas hipocoradas (++/4+), estertores crepitantes em ambos os hemitórax, abdômen globoso com Piparote positivo e edema de face e membros inferiores (++/4+). Trazia exames que mostravam anemia normocrômica e normocítica, parasitológico de fezes negativo e um sumário de urina com 2++ de proteína sem outras anormalidades. Baseado nesses dados, que exames devem ser solicitados e qual sua principal hipótese diagnóstica:","options":{"A":"Proteinúria de 24 horas, dosagem de ureia e creatinina; insuficiência renal crônica.","B":"Ecocardiograma transtorácico; insuficiência cardíaca congestiva.","C":"Coagulograma, Ultrassonografia abdominal; cirrose hepática.","D":"Ultrassonografia transvaginal; neoplasia de colo uterino.","E":"T4 livre e TSH; hipotireoidismo."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963407","ankiGuid":"dl{lM:C9r"},{"id":"anki-ginecologia-cancer-de-colo-uterino-13178d240f3e950f","number":"0236r","sourceNumber":"0236r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"J.G.H., 51 anos, G5 P5 C0 A0, sexarca aos 12 anos de idade, sem parceiro fixo, sem comorbidades, tabagista de 10 cigarros/dia e drogas ilícitas ocasionais, sem acompanhamento ginecológico há 8 anos, realizou exames de rotina com os seguintes resultados: Colpocitologia oncótica: lesão intraepitelial de alto grau (NIC III). O resultado da colposcopia com a biópsia foi a seguinte: achados colposcópicos anormais maiores (sugestivos de lesão de alto grau) com resultado anatomopatológico da biópsia: carcinoma micro invasor. A respeito desse caso de câncer de colo de útero, considere as afirmações e assinale a opção correta. 1. É o câncer ginecológico mais comum no Brasil. 2. É um câncer que realmente pode ser prevenido com os métodos atuais de rastreamento. 3. A paciente citada apresenta somente dois fatores de risco para o câncer de colo uterino. 4. O papilomavírus humano (HPV) está envolvido na carcinogênese em mais de 99% dos casos de câncer cervical. 5. A fase inicial do câncer de colo uterino geralmente é assintomática ou oligossintomática.","options":{"A":"Somente 1, 2, 4 e 5 estão corretas.","B":"Somente 1, 2 e 4 estão corretas.","C":"Somente 2, 4 e 5 estão corretas.","D":"Somente 2 e 4 estão corretas.","E":"Todas estão corretas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963408","ankiGuid":"CB^6m%AM>K"},{"id":"anki-ginecologia-cancer-de-colo-uterino-e4b16045558cb24a","number":"0237r","sourceNumber":"0237r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 39 anos de idade, IIG,IIP, apresenta lesão intraepitelial de alto grau de colo do útero em exame citológico. A colposcopia identifica área de mosaico adentrando o canal endocervical. A biópsia da lesão é compatível com microinvasão estromal. O passo seguinte é","options":{"A":"histeroscopia diagnóstica.","B":"histerectomia total.","C":"repetir colposcopia com estrogenioterapia.","D":"curetagem uterina.","E":"conização."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963409","ankiGuid":"GA=e.]wU>t"},{"id":"anki-ginecologia-cancer-de-colo-uterino-027f1809ad7403c7","number":"0238r","sourceNumber":"0238r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente com neoplasia de colo de útero, em tratamento com radioquimioterapia, apresentando sangramento vaginal, evoluiu com dor e edema no membro inferior direito. Qual a sua conduta para tratamento no caso clínico da questão anterior?","options":{"A":"Filtro de veia cava.","B":"Anticoagulação plena com enoxeparina.","C":"Amputação da perna.","D":"Aumento da ingesta via oral de proteínas.","E":"Revascularização de perna direita por angioplastia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963410","ankiGuid":"yS8$rj0Y-C"},{"id":"anki-ginecologia-cancer-de-colo-uterino-58830c0429cc1fcc","number":"0239r","sourceNumber":"0239r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente com neoplasia de colo de útero, em tratamento com radioquimioterapia, apresentando sangramento vaginal, evoluiu com dor e edema no membro inferior direito. Qual a sua hipótese diagnóstica?","options":{"A":"Varizes de MMII.","B":"Edema por desproteinemia devido a neoplasia.","C":"Úlcera de perna direita.","D":"Trombose venosa profunda.","E":"Isquemia crítica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963411","ankiGuid":"pJ;:M$[CT<"},{"id":"anki-ginecologia-cancer-de-colo-uterino-b7bac55ea952f35d","number":"0240r","sourceNumber":"0240r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente com 42 anos, último exame citológico há 6 anos. Procurou assistência devido ao fato de estar apresentando sangramento após todas a relações sexuais e dor discreta há 04 meses, e ainda, metrorragia há 2 meses. Durante o exame ginecológico evidenciou-se colo volumoso, endurecido, com áreas de sangramento que ocupa o terço superior da vagina. Paciente não permitiu realização do toque retal. O diagnóstico provável, o exame mais adequado e o tratamento mais indicado nesse caso são, respectivamente:","options":{"A":"Tumor endocervical, citologia endometrial e radioterapia.","B":"Tumor endocervical, biopsia endometrial e inserção de endoceptivo intrauterino.","C":"Tumor do colo uterino, biópsia do colo uterino e histerectomia total e salpingooforectomia bilateral.","D":"Tumor do colo uterino, citologia oncótica e hormônio terapia até o resultado."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963412","ankiGuid":"JALxx:{/gt"},{"id":"anki-ginecologia-cancer-de-colo-uterino-c6316f9b9085bb57","number":"0241r","sourceNumber":"0241r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Em relação ao câncer do colo do útero, é correta a seguinte afirmação:","options":{"A":"o tabagismo não é um fator de risco pois recentemente se descobriu que a causa é a infecção pelo HPV.","B":"o câncer do colo do útero pode se propagar por contiguidade, continuidade por via linfática e por via hematogênica.","C":"o tipo histológico mais comum é o adenocarcinoma mucinoso.","D":"a diferenciação entre ca in situ e invasivo só pode ser feita com a colposcopia e biópsia do colo.","E":"o acometimento dos paramétrios é diagnosticado pelo toque vaginal e ultrassonografia transvaginal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963413","ankiGuid":"j=y(~`TKSH"},{"id":"anki-ginecologia-cancer-de-colo-uterino-c507f5ad4ba6443c","number":"0242r","sourceNumber":"0242r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Em relação à prevenção do carcinoma do colo do útero é falso:","options":{"A":"A coleta tríplice de colpocitologia oncótica consiste na coleta do material do fundo de saco vaginal posterior, ectocérvice e endocérvice.","B":"A colposcopia permite localizar no colo do útero as lesões pré malignas e o carcinoma invasivo inicial, podendo ser utilizado isoladamente como método de detecção e rastreamento desta neoplasia.","C":"Ao interpretar-se o teste de Schiller as áreas iodo positivas são Schiller negativas e as áreas Iodo negativas são Schiller positivas.","D":"A conização do colo do útero pode ser útil quando a paciente apresenta citologia oncótica compatível com carcinoma in situ ou displasia grave, não observando à colposcopia imagens suspeitas.","E":"Lesões macroscópicas suspeitas no colo do útero devem ser biopsiadas sem aguardar o resultado da colpocitologia oncótica."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963414","ankiGuid":"v*OS%iq,30"},{"id":"anki-ginecologia-cancer-de-colo-uterino-bed54ca4f4001015","number":"0243r","sourceNumber":"0243r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Para se tomar conduta em caso de câncer de colo do útero, o estadiamento é muito importante. Em uma mulher cujo câncer invadiu o paramétrio, porém não até a parede pélvica, o estadio é:","options":{"A":"I B.","B":"II A.","C":"II B.","D":"III A.","E":"III B."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963415","ankiGuid":"Gx./6;d:z+"},{"id":"anki-ginecologia-cancer-de-colo-uterino-1dcefa344bfa312f","number":"0244r","sourceNumber":"0244r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O secretário municipal de saúde de uma pequena cidade do interior decidiu investir mais recursos na prevenção primária do câncer de colo do útero. Qual das alternativas a seguir pode ser classificada como estratégia de prevenção primária desta doença?","options":{"A":"Implantação de serviço de cirurgia oncológica no município.","B":"Vacinação de adolescentes sem vida sexual ativa.","C":"Aumento do número de exames de colposcopia para cada mulher.","D":"Rastreamento por meio do exame de Papanicolau a cada 6 meses.","E":"Implantação de serviço de radioterapia e quimioterapia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963416","ankiGuid":"yUHD4;<*B;"},{"id":"anki-ginecologia-cancer-de-colo-uterino-9c56ea12b6c9b252","number":"0245r","sourceNumber":"0245r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente, 45 anos, com carcinoma espinocelular de colo uterino e dilatação pielocalicial direita por obstrução ureteral distal. Qual dos seguintes exames apresentará o achado que está associado à obstrução ureteral?","options":{"A":"Toque vaginal.","B":"Exame especular.","C":"Colposcopia.","D":"Sedimento urinário.","E":"Toque retal."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963417","ankiGuid":"vR5e4C?3Q$"},{"id":"anki-ginecologia-cancer-de-colo-uterino-59cb33790b089afd","number":"0246r","sourceNumber":"0246r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 40 anos de idade com carcinoma espinocelular de colo do útero visível no exame especular com cerca de 5cm, sangrante em pequena quantidade. A lesão compromete o colo e a vagina, até cerca de 2cm do introito. Não foi realizado toque vaginal por receio de aumentar o sangramento. Com essas informações, o tratamento inicial proposto deve be?","options":{"A":"Traquelectomia com radioterapia.","B":"Quimio e radioterapia sem cirurgia.","C":"Cirurgia de Wertheim-Meigs e quimioterapia.","D":"Histerectomia total abdominal, quimio e radioterapia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963418","ankiGuid":"g+AeagvbLI"},{"id":"anki-ginecologia-cancer-de-colo-uterino-edcb60042a60444e","number":"0247r","sourceNumber":"0247r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O Ministério da Saúde do Brasil recomenda como medida de prevenção do câncer de colo do útero:","options":{"A":"Vacinação tetravalente contra HPV em adolescentes femininas, imunossuprimidos, usuário de drogas injetáveis e profissionais do sexo.","B":"A cauterização de lesões intraepiteliais de alto grau quando há detecção de HPV em mulheres acima de 35 anos de idade.","C":"Detecção precoce de lesões precursoras com exame citológico cervicovaginal em mulheres entre 25 e 64 anos de idade.","D":"Colposcopia com biópsia dirigida nos casos células escamosas atípicas de significado indeterminado em exame citológico de mulheres com mais de 35 anos de idade."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963419","ankiGuid":"wB&w!vn6_["},{"id":"anki-ginecologia-cancer-de-colo-uterino-343573c2396fcd5c","number":"0248r","sourceNumber":"0248r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma mulher de 52 anos apresenta carcinoma de colo uterino. No exame especular visualiza-se massa no colo de 5 cm, invadindo 2 cm da parte superior da vagina à esquerda. Biópsia revela invasão estromal maior que 3 mm. Toque vaginal e retal: paramétrios livres. Todos os demais exames indicados para estadiamento estão normais. Assinale a alternativa que indica, respectivamente, o estadiamento clínico (FIGO) e o tratamento indicado.","options":{"A":"Estágio I b – cirurgia","B":"Estágio II a – cirurgia","C":"Estágio II b – radioterapia","D":"Estágio III a – cirurgia","E":"Estágio III b – radioterapia"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963420","ankiGuid":"B%!:#x7%*&"},{"id":"anki-ginecologia-cancer-de-colo-uterino-cea4396fa80e4d9a","number":"0249r","sourceNumber":"0249r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 50 anos, GIII PIII é encaminhada pelo SISREG ao ambulatório de patologia cervical com laudo citopatológico de NIC III. A colposcopia evidenciou vasos atípicos. Realizado biópsia dirigida com laudo histopatológico de microinvasão. A conduta preconizada, nesse caso, é:","options":{"A":"conização a frio","B":"histerectomia total abdominal","C":"histerectomia radical modificada com linfadenectomia pélvica","D":"histerectomia total radical modificada sem linfadenectomia pélvica"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963421","ankiGuid":"BLaZ90Ib#("},{"id":"anki-ginecologia-cancer-de-colo-uterino-6b47984b4862bff9","number":"0250r","sourceNumber":"0250r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 40 anos, casada, G5P5, IMC=27,0; Método contraceptivo = laqueadura tubária, procura serviço médico com queixa de sinusorragia, sangramento uterino anormal e corrimento vaginal fétido que iniciaram há 06 meses. É portadora de diabetes mellitus e hipertensão arterial. O exame físico ginecológico com introdução de espéculo mostrou sangramento vaginal moderado e presença de tumor vegetante atingindo até terço inferior da vagina. Baseado nesses dados, escolha a opção que traz a conduta mais adequada para o caso.","options":{"A":"Solicitar ultrassonografia transvaginal para investigação inicial do sangramento uterino anormal.","B":"Paciente de alto risco para câncer do endométrio - solicitar histeroscopia diagnóstica.","C":"Prescrever ácido tranexâmico IM para cessar o sangramento e em seguida realizar exame de papanicolau para adequada avaliação do colo uterino.","D":"Realizar biópsia da lesão vaginal.","E":"Solicitar Tomografia Computadorizada de pelve para estadiamento do tumor."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963422","ankiGuid":"ocs`Q`Q7jY"},{"id":"anki-ginecologia-cancer-de-colo-uterino-d8893dc93015f8a8","number":"0251r","sourceNumber":"0251r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 30 anos, G5 P5, com queixa de sangramento genital durante o ato sexual, há três meses. Durante o exame ginecológico, foi observada lesão cervical de um centímetro em seu maior diâmetro, restrita ao colo uterino. A vagina se encontra livre de lesões, assim como os paramétrios. Considerando a possibilidade diagnóstica de neoplasia cérvice uterina, assinale a alternativa que representa o estadiamento adequado.","options":{"A":"Ia1","B":"Ib3","C":"Ib1","D":"IIa","E":"IIb"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963423","ankiGuid":"o^%CXwx|$_"},{"id":"anki-ginecologia-cancer-de-colo-uterino-cabf9c7839d76441","number":"0252r","sourceNumber":"0252r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 45 anos, com citologia cérvico-vaginal positiva para células neoplásicas escamosas, foi submetida a colposcopia com biópsia do colo que revelou carcinoma de células escamosas invasor. O estadiamento clínico do tumor foi compatível com Estágio IB1. Em relação à conduta neste caso, é CORRETO afirmar que:","options":{"A":"Está indicada a traquelectomia clássica para completar o estadiamento e orientar o tratamento definitivo.","B":"Está indicada Quimio-irradiação neo-adjuvante.","C":"Está indicada a cirurgia de Wertheim-Meigs.","D":"Está indicada a Ressonância Magnética, ou Tomografia Computadorizada da pelve e do abdome. Se não houver sinais de comprometimento linfonodal, realizar histerectomia total com anexectomia bilateral."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963424","ankiGuid":"BoCs]~uK8]"},{"id":"anki-ginecologia-cancer-de-colo-uterino-ca14c8700a17d8d3","number":"0253r","sourceNumber":"0253r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O câncer de colo uterino pode-se propagar diretamente por continuidade e por contiguidade. A propagação indireta será:","options":{"A":"Para paramétrios.","B":"Por via linfática e hemática.","C":"Pare bexiga e reto.","D":"Para paracolpos."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963425","ankiGuid":"D9Kx$^DG/:"},{"id":"anki-ginecologia-cancer-de-colo-uterino-c02bd6927032ba4c","number":"0254r","sourceNumber":"0254r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Considere um paciente de 88 anos de idade, hipertensa, diabética tipo 2, em uso de insulina e com quadro de insuficiência cardíaca NYHA classe III. Ela foi diagnosticada com câncer de colo uterino estágio IIIB pela classificação da FIGO (2009). Na última ecografia de aparelho urinário, foi visualizada hidronefrose moderada à direita. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Considerando o status funcional da paciente, as comorbidades envolvidas e o tratamento proposto para a neoplastia em questão, deve-se introduzir a ideia de cuidados paliativos com familiares e paciente, visando, entre outros, ao bem-estar, apesar da evolução da doença, e ao manejo álgico adequado.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963426","ankiGuid":"Be6ZDvU{bO"},{"id":"anki-ginecologia-cancer-de-colo-uterino-52ab283feb8a479d","number":"0255r","sourceNumber":"0255r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Considere um paciente de 88 anos de idade, hipertensa, diabética tipo 2, em uso de insulina e com quadro de insuficiência cardíaca NYHA classe III. Ela foi diagnosticada com câncer de colo uterino estágio IIIB pela classificação da FIGO (2009). Na última ecografia de aparelho urinário, foi visualizada hidronefrose moderada à direita. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Os achados de hidronefrose ou rim não funcionante devem ser incluídos no estadiamento no câncer de colo uterino, quando excluídas outras causas.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963427","ankiGuid":"j@H~(}%2S+"},{"id":"anki-ginecologia-cancer-de-colo-uterino-6e6a107983eea909","number":"0256r","sourceNumber":"0256r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Considere um paciente de 88 anos de idade, hipertensa, diabética tipo 2, em uso de insulina e com quadro de insuficiência cardíaca NYHA classe III. Ela foi diagnosticada com câncer de colo uterino estágio IIIB pela classificação da FIGO (2009). Na última ecografia de aparelho urinário, foi visualizada hidronefrose moderada à direita. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. A paciente pode ser tratada com quimiorradioterapia primária.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963428","ankiGuid":"LG(c(+@hZS"},{"id":"anki-ginecologia-cancer-de-colo-uterino-59e8c771adb5bdaf","number":"0257r","sourceNumber":"0257r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 50 anos de idade vai a consulta em UBS com queixa de corrimento vaginal acinzentado e com odor fétido na última semana. Refere também que gostaria de realizar check-up, pois não se consulta com médico há mais de 10 anos e está preocupada, pois a própria mãe foi diagnosticada com câncer de mama quando tinha 68 anos de idade. História médica pregressa: G6P6A0, diagnóstico prévio de sífilis tratada recentemente e coitarca aos 14 anos de idade. Tabagista de um maço de cigarro ao dia desde os 15 anos de idade. Considerando esse caso clínico e os conhecimentos médicos relacionados à saúde da mulher, julgue o item a seguir. O fato de ter apresentado quadro de sífilis anteriormente não eleva o risco de a paciente vir a desenvolver câncer de colo uterino.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963429","ankiGuid":"N{=dCW|7(u"},{"id":"anki-ginecologia-cancer-de-colo-uterino-6e94b6daa384ee53","number":"0258r","sourceNumber":"0258r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de 50 anos de idade vai a consulta em UBS com queixa de corrimento vaginal acinzentado e com odor fétido na última semana. Refere também que gostaria de realizar check-up, pois não se consulta com médico há mais de 10 anos e está preocupada, pois a própria mãe foi diagnosticada com câncer de mama quando tinha 68 anos de idade. História médica pregressa: G6P6A0, diagnóstico prévio de sífilis tratada recentemente e coitarca aos 14 anos de idade. Tabagista de um maço de cigarro ao dia desde os 15 anos de idade. Considerando esse caso clínico e os conhecimentos médicos relacionados à saúde da mulher, julgue o item a seguir. Deverá ser solicitado o exame colpocitológico para rastreamento de neoplasia de colo uterino, cujo principal fator de risco são as infecções do HPV, particularmente os subtipos 16 e 18.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963430","ankiGuid":"rgzQ7Gk%r)"},{"id":"anki-ginecologia-cancer-de-colo-uterino-bcffb5bac9ad5c11","number":"0259r","sourceNumber":"0259r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 35 anos de idade, apresenta sinusorragia. Exame especular: lesão vegetante, friável e sangrante no colo do útero com 3,5 cm de diâmetro. Toque retal: paramétrios livres. Biópsia: carcinoma espinocelular do colo do útero G2. Assinale a alternativa que contém o estadiamento e tratamento corretos:","options":{"A":"Ib1; cirurgia de Wertheim-Meigs.","B":"Ib2; quimiorradioterapia.","C":"Ib2; cirurgia de Wertheim-Meigs.","D":"Ib3; quimiorradioterapia.","E":"Ib3; Wertheim-Meigs."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963431","ankiGuid":"zFD(l|^A2%"},{"id":"anki-ginecologia-cancer-de-colo-uterino-e2a1f5668a5ca199","number":"0260r","sourceNumber":"0260r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O câncer de colo uterino é o câncer ginecológico mais comum nas mulheres. No que diz respeito a essa temática, julgue o item a seguir. O adenocarcinoma surge das células colunares produtoras de muco da endocérvice.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963432","ankiGuid":"sFw}d,f/a@"},{"id":"anki-ginecologia-cancer-de-colo-uterino-681bc81c12f04214","number":"0261r","sourceNumber":"0261r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O câncer de colo uterino é o câncer ginecológico mais comum nas mulheres. No que diz respeito a essa temática, julgue o item a seguir. O local típico de surgimento do carcinoma de células escamosas do colo uterino é a junção escamocolunar.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963433","ankiGuid":"b/Mqe!0aBC"},{"id":"anki-ginecologia-cancer-de-colo-uterino-485ec9ef86a69758","number":"0262r","sourceNumber":"0262r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O câncer de colo uterino é o câncer ginecológico mais comum nas mulheres. No que diz respeito a essa temática, julgue o item a seguir. Os subtipos 6 e 11 são os mais relacionados ao carcinoma de células escamosas de colo uterino.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963434","ankiGuid":"PJ{@Zt2Rma"},{"id":"anki-ginecologia-cancer-de-colo-uterino-510b0449f02cfe14","number":"0263r","sourceNumber":"0263r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma mulher de 45 anos procura ginecologista para tratar um corrimento marrom, fétido. Por habitar zona rural, ficou os últimos 10 anos sem controles de rotina. Ao exame físico, é evidenciada massa friável ocupando colo uterino e região parametrial bilateral. Realizado urografia excretora que demonstra rim esquerdo não funcionante. O estadiamento dessa neoplasia é:","options":{"A":"IIA.","B":"IIB.","C":"IIIA.","D":"IIIB."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963435","ankiGuid":"QlhV%2b-9u"},{"id":"anki-ginecologia-cancer-de-colo-uterino-72497954a7ebccd5","number":"0264r","sourceNumber":"0264r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 41a, G3P3A0C0, menstruação regular, laqueada, nega comorbidades, retorna com resultado de exames após citologia oncótica com presença de células glandulares atípicas, sem outras especificações; Exame ginecológico: colposcopia adequada com zona de transformação tipo 2 e epitélio acetobranco denso adentrando canal endocervical; toque vaginal: colo fibroelástico medindo 3cm, útero ântero-verso fletido, móvel e indolor, de tamanho, forma e consistência normais, anexos não palpáveis; ultrassonografia transvaginal: sem alterações, com linha endometrial de 12mm, compatível com a fase do ciclo menstrual. Biópsia: adenocarcinoma in situ. A CONDUTA É:","options":{"A":"Solicitar teste de HPV para determinação de tipo oncogênico.","B":"Realizar conização de colo uterino.","C":"Solicitar biópsia de endométrio.","D":"Realizar histerectomia total."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963436","ankiGuid":"L6%8SqHW]x"},{"id":"anki-ginecologia-cancer-de-colo-uterino-27c614694e7cf821","number":"0265r","sourceNumber":"0265r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Para diagnóstico definitivo de carcinoma in situ do colo do útero, são necessários(as):","options":{"A":"colpocitologia com lesão de alto grau e colposcopia evidenciando lesão acetobranca.","B":"colpocitologia com lesão de alto grau e colposcopia com biópsia evidenciando cacinoma in situ do colo.","C":"colpocitologia com lesão de alto grau, colposcopia com biópsia evidenciando carcinoma in situ do colo e cortes histológicos seriados de peça proveniente de cone com acometimento da membrana basal e com margens livres.","D":"colpocitologia com lesão de alto grau, colposcopia com biópsia evidenciando carcinoma in situ do colo e cortes histológicos seriados de peça proveniente de cone sem acometimento da membrana basal e com margens livres.","E":"colpocitologia com lesão de alto grau, colposcopia com biópsia evidenciando carcinoma in situ do colo e cortes histológicos seriados de peça proveniente de cone sem acometimento da membrana basal e sem margens livres."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963437","ankiGuid":"fhh&c?1+Bk"},{"id":"anki-ginecologia-cancer-de-colo-uterino-cf47fbf8e1809084","number":"0266r","sourceNumber":"0266r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 47 anos, proveniente de São Raimundo Nonato-PI, refere sinusorragia há 5 meses. Ciclos pouco irregulares nos últimos 3 meses com sangramento persistente em menor intensidade, logo após a menstruação. Refere ainda leucorreia amarelada de odor fétido. Menarca aos 12 anos. Sexarca aos 15 anos. G8 P6 (N) A2. Laqueadura tubária aos 30 anos. Última citologia oncótica há 7 anos. Exame especular: lesão exofítica sangrante ao toque da espátula. Toque: útero pouco aumentado de volume, móvel, algo doloroso, lesão endurecida em topografia de colo, que se estende aos fórnices vaginais e atinge paramétrio lateral direito. Sangramento aumentado, logo após o exame ginecológico. Assinale a alternativa CORRETA sobre o caso descrito:","options":{"A":"A suspeita clinica é de câncer de colo uterino e faz-se necessária biópsia de colo para confirmação e início do tratamento que deverá ser a Radioterapia com quimioterapia sensibilizante.","B":"A suspeita clinica é de câncer de colo uterino, sendo necessário a colposcopia seguida de conização para a confirmação diagnóstica, somente em seguida iniciar o tratamento.","C":"A suspeita clínica é de câncer de colo uterino. Após a confirmação histopatológica, a paciente deverá ser submetida a laparotomia exploradora para o correto estadiamento da doença.","D":"A suspeita clínica é de câncer de endométrio com comprometimento de colo (Estadio II), devendo a paciente ser submetida a tratamento cirúrgico para estadiamento completo e tratamento oncológico.","E":"A suspeita clínica é de câncer de colo uterino Estádio IB, devendo a paciente ser submetida a Histerectomia de Wertheim-Meigs, após a confirmação histopatológica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963438","ankiGuid":"Ixa<pKdu3T"},{"id":"anki-ginecologia-cancer-de-colo-uterino-38a3e95bcf5397cf","number":"0267r","sourceNumber":"0267r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 50 anos de idade queixa-se de sangramento diário em pequena quantidade, de odor fétido, que aumenta de volume ao ter relação sexual. Ao exame especular, observa-se conteúdo vaginal sanguinolento, de forte odor e lesão friável, vegetante, 5 cm, ocupando o lábio posterior do colo e o terço superior da vagina. Relizada coleta de citologia oncológica cervicovaginal e biópsia da lesão, espera-se encontrar, respectivamente","options":{"A":"Citologia - atipia de significado indeterminado (ASC-US); biópisia - carcinoma de células claras","B":"Citologia - atipias em que não se pode descartar HSIL (ASC-H); biópisia - carcinoma indiferenciado","C":"Citologia - lesão intraepitelial escamosa de alto grau (LIA G); biópisia - adenocarcinoma","D":"Citologia - carcinoma escamoso invasivo; biópisia - carcinoma espinocelular"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963439","ankiGuid":"4lD![B+z/"},{"id":"anki-ginecologia-cancer-de-colo-uterino-b403df5e7e37cab1","number":"0268r","sourceNumber":"0268r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma paciente de trinta anos de idade, com o diagnóstico de carcinoma espinocelular do colo uterino estádio 1A2, realizou cirurgia e retornou no pós-operatório para avaliação de radioterapia. Nessa situação hipotética, não é indicação de radioterapia a presença de","options":{"A":"um tamanho tumoral acima de 5 cm, apenas.","B":"margens cirúrgicas comprometidas.","C":"invasão linfonodal.","D":"invasão de paramétrio.","E":"invasão angiolinfática associada à invasão estromal de 2/3."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963440","ankiGuid":"jk4)jUv$(<"},{"id":"anki-ginecologia-cancer-de-colo-uterino-3198f75a77ea2582","number":"0269r","sourceNumber":"0269r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 47 anos apresenta resultado de citologia oncótica cervical compatível com lesão intraepitelial escamosa de alto grau. Submetida à colposcopia sendo identificada lesão ulcerada acetorreagente às 9h do colo uterino. Biópsia da referida lesão confirmou a presença de carcinoma escamoso invasor. O próximo passo da propedêutica é a realização de","options":{"A":"cone a frio para estadiamento e posterior indicação de radioquimioterapia.","B":"cirurgia de alta frequência para estadiamento e posterior indicação de radioquimioterapia.","C":"estadiamento clínico para posterior indicação de histerectomia radical ampliada (cirurgia de Wertheim-Meigs).","D":"cirurgia de alta frequência para estadiamento e posterior indicação de tratamento cirúrgico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963441","ankiGuid":"oxR1&VM/yo"},{"id":"anki-ginecologia-cancer-de-colo-uterino-e2c31550685deb0a","number":"0270r","sourceNumber":"0270r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 50 anos de idade, com carcinoma espinocelular de colo do útero que atinge o terço inferior da vagina, refere sangramento vaginal pequeno e diário. Não apresenta outras comorbidades e não é obesa. O tratamento indicado é","options":{"A":"histerectomia ampliada, salpingooforectomia bilateral, linfadenectomia pélvica e periaórtica.","B":"radioterapia.","C":"hormonioterapia e quimioterapia neoadjuvante.","D":"histerectomia total com colpectomia e linfadenectomia pélvica.","E":"cirurgia de Werthein-Meigs."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963442","ankiGuid":"MN!ur[;gtC"},{"id":"anki-ginecologia-cancer-de-colo-uterino-8d0b7f2ed0d20a05","number":"0271r","sourceNumber":"0271r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente com tumor de colo uterino, estadiado em IA2, qual o tratamento mais indicado?","options":{"A":"Radioterapia exclusiva.","B":"Histerectomia radical e linfadenectomia pélvica.","C":"Quimioterapia exclusiva.","D":"Traquelectomia.","E":"Associação de quimioterapia e radioterapia."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963443","ankiGuid":"FyM6.fLs6v"},{"id":"anki-ginecologia-cancer-de-colo-uterino-a8c483fe675ef1a8","number":"0272r","sourceNumber":"0272r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 34 anos, com 3 filhos, sem queixa clínica, procurou ambulatório de ginecologia para consulta de rotina. O exame ginecológico foi normal. A Colpocitologia colhida revelou como resultado neoplasia intraepitelial grau III (NIC 3). Foi submetida à colposcopia, que revelou lesão em mosaico às 11 horas. Feita a biópsia, o exame anatomopatológico revelou carcinoma in situ. A conduta a ser adotada é","options":{"A":"histerectomia total sem anexectomia.","B":"histerectomia total com anexectomia.","C":"histerectomia total com linfadenectomia pélvica.","D":"conização do colo uterino.","E":"cirurgia de Werthein-Meigs."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963444","ankiGuid":"rG6q_ObK~a"},{"id":"anki-ginecologia-cancer-de-colo-uterino-3864c1d1080fd6fb","number":"0273r","sourceNumber":"0273r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 43 anos, com diagnóstico histopatológico de carcinoma espinocelular de colo uterino. O exame retal evidencia comprometimento extenso de paramétrios, com espessamento e nodulações, atingindo até parede pélvica. Uma das principais complicações do câncer de colo uterino nesse estádio é","options":{"A":"Fístula uretero-intestinal.","B":"Abdome agudo hemorrágico.","C":"Fístula uretrovaginal.","D":"Insuficiência renal pré-renal.","E":"Obstrução ureteral."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963445","ankiGuid":"NPi$+998T3"},{"id":"anki-ginecologia-cancer-de-colo-uterino-cb73ab3f7290d157","number":"0274r","sourceNumber":"0274r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente 31 anos de idade, G4P4, com história de sangramento persistente e anemia ferropriva, foi diagnosticada com carcinoma espinocelular de colo uterino, estadiamento clínico IIB (estadiamento FIGO, 2009). Qual o tratamento mais adequado?","options":{"A":"Cirurgia de Wertheim Meigs.","B":"Braquiterapia + Quimioterapia.","C":"Radioterapia + Quimioterapia.","D":"Cirurgia de Wertheim Meigs + Braquiterapia + Quimioterapia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963446","ankiGuid":"PDVf5gfR2f"},{"id":"anki-ginecologia-cancer-de-colo-uterino-3b19b748ab8431d1","number":"0275r","sourceNumber":"0275r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 33 anos queixa-se de sangramento transvaginal persistente, com odor pútrido e grande desconforto pélvico. Ao exame: extensa lesão em colo uterino, friável, sangrante, com áreas ulceradas e de aspecto necrótico. A lesão estendia-se do colo uterino até terço superior da vagina e paramétrios, poupando terço inferior da vagina e sem extensão para parede pélvica. A biópsia diagnosticou carcinoma escamoso do colo uterino. O estadiamento e tratamento corretos são:","options":{"A":"Estádio IIB; quimiorradiação.","B":"Estádio IA1; histerectomia radical modificada.","C":"Estádio IB2; histerectomia radical e linfadenectomia.","D":"Estádio IIA2; quimiorradiação.","E":"Estádio IIIB; exenteração pélvica"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963447","ankiGuid":"ntUQhqLkJj"},{"id":"anki-ginecologia-cancer-de-colo-uterino-f9e2cb3b0a57f2da","number":"0276r","sourceNumber":"0276r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Qual o melhor tratamento para câncer cervical estagio Ib?","options":{"A":"Conização.","B":"Histerectomia.","C":"Histerectomia tipo II.","D":"Cirurgia de Wertheim-Meigs.","E":"Traquelectomia."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963448","ankiGuid":"s[I:AISXBn"},{"id":"anki-ginecologia-cancer-de-colo-uterino-8b9b10d44464311d","number":"0277r","sourceNumber":"0277r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Sobre o tratamento cirúrgico do carcinoma escamoso do colo uterino, é INCORRETO afirmar que:","options":{"A":"A parametrectomia consiste na ressecção dos ligamentos uterosacro, largo e redondo.","B":"O tumor está estritamente confinado ao colo uterino no estadiamento inicial (estádio I).","C":"A linfadenectomia pélvica consiste na retirada dos gânglios (linfonodos) da cadeia das artérias ilíacas interna, externa e comum.","D":"O tratamento cirúrgico do carcinoma inicial do colo na mulher com gravidez de 14 semanas segue o mesmo protocolo da mulher não grávida."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963449","ankiGuid":"yNp_Fa&S;~"},{"id":"anki-ginecologia-cancer-de-colo-uterino-dacec3e77e5c7f10","number":"0278r","sourceNumber":"0278r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Comparece para atendimento paciente de 26 anos, primigesta, com diagnóstico de carcinoma in situ do colo uterino confirmado por biópsia. A idade gestacional é de 30 semanas. Assinale a alternativa que apresenta a conduta CORRETA a ser adotada:","options":{"A":"Cirurgia de Alta Frequência (CAF).","B":"Conização cirúrgica.","C":"Acompanhamento durante a gravidez com reavaliação e tratamento pós parto.","D":"Interrupção da gestação para tratamento correto."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963450","ankiGuid":"IDHgn6rUV"},{"id":"anki-ginecologia-cancer-de-colo-uterino-478f73a472a2430e","number":"0279r","sourceNumber":"0279r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 53 anos recebe o diagnóstico de carcinoma de colo uterino, estadiamento IB1. A propagação mais frequente de metástase neste caso é:","options":{"A":"Linfática.","B":"Venosa.","C":"Contiguidade.","D":"Neural.","E":"Arterial."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963451","ankiGuid":"b=n,b;-~Iy"},{"id":"anki-ginecologia-cancer-de-colo-uterino-5df95edc52440906","number":"0280r","sourceNumber":"0280r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Assinale a tríade para o diagnóstico do Ca de colo uterino.","options":{"A":"Teste de schiller, colposcopia e histopatológico.","B":"Colpocitologia oncótica, teste do ácido acético e histopatológico.","C":"Colpocitologia oncótica, colposcopia e histopatológico.","D":"Colposcopia, histerosalpingografia e laparoscopia.","E":"Colpocitologia oncótica, histeroscopia e colposcopia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963452","ankiGuid":"mvK#v^K%{l"},{"id":"anki-ginecologia-cancer-de-colo-uterino-0a7c38dd13f98018","number":"0281r","sourceNumber":"0281r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Nas pacientes diagnosticadas com carcinoma do colo uterino, a opção de tratamento inicial mais adequada varia de acordo com estadiamento clínico. Desta forma, assinale qual das condutas abaixo não é a mais adequada.","options":{"A":"Histerectomia total é o tratamento recomendado para pacientes que apresentam tumor com invasão de até 3 mm, sem invasão linfática e vascular e sem dissecção linfonodal, pois o risco de metástases linfonodais é < que 1%.","B":"Nos estadios patológicos IB de risco alto IIB, recomenda-se tratamento adjuvante com radioterapia externa a braquiterapia concomitantemente à quimioterapia baseada em platina.","C":"A conização pode ser uma opção para pacientes que desejam manter fertilidade, mas que apresentam tumores com invasão menor que 3 mm, sem invasão linfática e vascular e margens livres.","D":"Para tumores com invasão acima de 3 mm ou com invasão linfática e vascular, o tratamento de rotina deve ser a histerectomia radical associada à técnica do linfonodo sentinela ou linfadenectomia pélvica bilateral, pois o risco de metástases linfonodais é de cerca de 5%.","E":"Nos estadios clínicos IIB, III e IVA, recomenda-se tratamento com radioterapia externa e braquiterapia."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963453","ankiGuid":"yI+!QyuG.i"},{"id":"anki-ginecologia-cancer-de-colo-uterino-15b59a02739f6700","number":"0282r","sourceNumber":"0282r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Sobre as neoplasias ginecológicas, assinale a opção CORRETA.","options":{"A":"A disseminação por via linfática é a principal forma de propagação do câncer de ovário.","B":"O câncer de endométrio possui lesão precursora estabelecida e passível de prevenção.","C":"O câncer de vulva é mais prevalente em mulheres jovens e tem o HPV como seu principal agente etiológico.","D":"A quimioterapia tem papel importante no tratamento do câncer do colo uterino.","E":"A radioterapia não tem indicação no tratamento do câncer de ovário."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963454","ankiGuid":"NLIn)j`.zM"},{"id":"anki-ginecologia-cancer-de-colo-uterino-db601c617f06c70c","number":"0283r","sourceNumber":"0283r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 35 anos, G6P6, partos vaginais, procura o serviço de atenção básica da comunidade, por apresentar sangramento genital discreto com odor desagradável há um mês. Sem demais queixas. O exame físico revela lesão ulcerada em colouterino, pouco sangrante, com áreas de necrose intensa. A lesão se estende ao terço superior da vagina, chegando a atingir a parede pélvica. Traz consigo um exame de Papanicolau de 2014, revelando alterações reativas metaplásicas. Considerando o cenário acima, qual o provável estadiamento clínico?","options":{"A":"Ib1","B":"IIa","C":"IIIb","D":"Ia2","E":"IIb"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963455","ankiGuid":"IDaE.HFWtq"},{"id":"anki-ginecologia-cancer-de-colo-uterino-7105d88c196a529f","number":"0284r","sourceNumber":"0284r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma mulher de 49 anos de idade realizou exame de citologia oncológica do colo, que revelou lesão intraepitelial de alto grau. Seu ginecologista então solicitou colposcopia e biópsia de área suspeita. O resultado foi carcinoma espinocelular invasivo e, após exame físico e análise de ressonância magnética, notou-se acometimento tumoral do terço proximal do paramétrio esquerdo. Com base nesse caso hipotético, assinale a alternativa que apresenta o tratamento mais adequado.","options":{"A":"cirurgia de Wertheim-Meigs","B":"cirurgia de traquelectomia e parametrectomia","C":"radioterapia e quimioterapia","D":"quimioterapia citorredutora, seguida de cirurgia de Wertheim-Meig","E":"radioterapia neoadjuvante com preparo para traquelectomia e parametrectomia"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963456","ankiGuid":"q8%GIk8QiP"},{"id":"anki-ginecologia-cancer-de-colo-uterino-d28c6c5d34f352a8","number":"0285r","sourceNumber":"0285r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O câncer de colo é um câncer ginecológico prevenível que acomete uma população mais jovem se comparado a outras malignidades ginecológicas. Sobre esse câncer é CORRETO afirmar que:","options":{"A":"Algumas mulheres se apresentam assintomáticas ao diagnóstico.","B":"Os adenocarcinomas são o grupo de câncer de colo mais prevalente entre os tumores de colo.","C":"O estadiamento é cirúrgico, com lavado peritoneal e linfadenectomia pélvica e paraórtica.","D":"A estenose ureteral piora o prognóstico, mesmo sem alterar o estadiamento."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963457","ankiGuid":"b#}MNJ8mRE"},{"id":"anki-ginecologia-cancer-de-colo-uterino-028aa9fe4abafcee","number":"0286r","sourceNumber":"0286r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Com referência ao câncer de colo uterino:","options":{"A":"A realização de rastreamento citológico faz-se necessário devido às caracterìsticas da evolução de suas lesões precursoras.","B":"A colposcopia está indicada quando forem encontradas anormalidades citológicas.","C":"Uma minoria dos casos relaciona-se à infecção por HPV, razão pela qual o uso de preservativos nas relações sexuais levou à redução do número deste tipo de câncer.","D":"O aumento do número de casos diagnosticados de câncer de mama e de pele fez com que esse tipo deixasse de ser um problema de saúde pública."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963458","ankiGuid":"g(LHx*2wmg"},{"id":"anki-ginecologia-cancer-de-colo-uterino-9afa27c12e761dce","number":"0287r","sourceNumber":"0287r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher, 42 anos, sangramento intermitente há cerca de 6 meses, comparece à consulta ginecológica para investigação. À colposcopia, apresenta lesão acetobranca no colo uterino. Não se evidenciou lesões vaginais. Ao toque retal, observou-se útero de volume normal e paramétrios sem anormalidades. A biópsia excisional por cirurgia de alta frequência revelou carcinoma escamoso com invasão estromal de 7 mm de profundidade. Qual o tratamento mais provável para essa paciente?","options":{"A":"Histerectomia radical sem anexectomia.","B":"Histerectomia tipo II e anexectomia.","C":"Histerectomia vaginal.","D":"Radioterapia pélvica."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963459","ankiGuid":"iV?4gvfET!"},{"id":"anki-ginecologia-cancer-de-colo-uterino-25b544185754709a","number":"0288r","sourceNumber":"0288r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente com câncer de colo uterino com lesão confinada ao colo menor que 4 cm, corresponde ao estadiamento:","options":{"A":"IA.","B":"IA2.","C":"IB1.","D":"IB2."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963460","ankiGuid":"CmOx}ruJ;7"},{"id":"anki-ginecologia-cancer-de-colo-uterino-14dba6c96ae4076e","number":"0289r","sourceNumber":"0289r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O câncer de colo uterino acomete mulheres jovens, em idade economicamente ativa, com maior concentração entre 45 e 50 anos. O fator etiológico é a infecção persistente pelo papilomavírus humano (HPV). Sobre o estadiamento e o tratamento dessa patologia, dadas as afirmativas: I. No estádio IIa, o tumor é de qualquer magnitude, porém com infiltração do terço superior da vagina. Na maioria dos casos, são detectados apenas no pós-operatório de histerectomias radicais por meio da análise histológica da peça, que apresenta infiltração microscópica. II. Pode-se optar por conização com margens livres em pacientes com desejo reprodutivo que foram diagnosticadas no estágio Ia1. III. Para o estágio IVa, onde se identifica metástases a distância, como pulmonar e hepática, o tratamento é basicamente paliativo. Verifica-se que está(ão) correta(s) apenas","options":{"A":"II.","B":"III.","C":"I e II.","D":"I e III.","E":"II e III."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963461","ankiGuid":"Lq1GC-E.^z"},{"id":"anki-ginecologia-cancer-de-colo-uterino-4252d379ea709b89","number":"0290r","sourceNumber":"0290r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"O carcinoma cervical é a terceira malignidade ginecológica no mundo. Sobre essa neoplasia, assinale a opção CORRETA:","options":{"A":"O Papanicolau não é um exame sensível para o diagnóstico do subtipo do adenocarcinoma de célula claras.","B":"A disseminação ocorre principalmente pela via hematogênica.","C":"O câncer cervical se origina no epitélio escamoso maduro, propagando-se para a endocérvice após anos do seu aparecimento.","D":"O mais importante preditor de recorrência da doença é o estado dos linfonodos para aóticos."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963462","ankiGuid":"OE#~<M]j&k"},{"id":"anki-ginecologia-cancer-de-colo-uterino-4129f22581edceaa","number":"0291r","sourceNumber":"0291r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 41 anos, G3 P3 (N) A0, casada, do lar, realizou citologia oncótica de rastreamento, cujo resultado foi lesão de alto grau. A colposcopia mostrou extensa área aceto-reativa, cuja biópsia revelou tratar-se de carcinoma epidermóide invasor, grau 2 de colo uterino. Ao exame físico, útero em AVF, intra-pélvico, móvel e indolor, paramétrios livres. Exame especular: colo do útero com área de mácula rubra localizada. Descreva qual a melhor conduta terapêutica e em que a mesma consiste.","options":{"A":"A paciente deverá ser submetida a conização para confirmação diagnóstica, e sendo as margens livres, a paciente pode ser considerada tratada.","B":"A paciente deverá ser submetida a cirurgia de Werteim-Meigs, seguida de Radioterapia + quimioterapia adjuvante, sendo o prognóstico considerado bom.","C":"A paciente deverá ser submetida a Histerectomia total simples com salpingectomia bilateral, uma vez que se trata de lesão em estádio inicial.","D":"A paciente deverá ser submetida a Radioterapia + quimioterapia, uma vez que se trata de lesão epidermoide, com excelente resposta à radioterapia.","E":"A paciente deverá ser submetida a Histerectomia Total ampliada, sem a necessidade de tratamento complementar."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963463","ankiGuid":"l5p[l}6%3?"},{"id":"anki-ginecologia-cancer-de-colo-uterino-818cbb6cc2efcfe2","number":"0292r","sourceNumber":"0292r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Qual é o tipo de câncer mais comum no colo uterino?","options":{"A":"Adenocarcinoma.","B":"Carcinoma adenoescamoso.","C":"Metaplasia escamosa.","D":"Carcinoma de células escamosas.","E":"Carcinoma endometrioide."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963464","ankiGuid":"o$If/5V[>M"},{"id":"anki-ginecologia-cancer-de-colo-uterino-57dd4c746303d677","number":"0293r","sourceNumber":"0293r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 31 anos, com 2 filhos por partos normais e sem queixa clínica, realizou consulta ginecológica de rotina. Relata ter feito laqueadura tubária há 1 ano. O exame ginecológico foi normal. A colpocitologia colhida revelou ser sugestiva de neoplasia cervical de baixo grau (NIC 1). Foi solicitada colposcopia que revelou, na posição 2 horas, lesão com aspecto de mosaico, e foi realizada biópsia nesse local. O exame anatomopatológico da biópsia revelou carcinoma in situ. Diante desses achados, a melhor conduta é:","options":{"A":"Histerectomia total com preservação dos anexos.","B":"Histerectomia total com anexectomia bilateral.","C":"Cirurgia de Wertheim-Meigs.","D":"Cauterização do colo uterino.","E":"Conização do colo uterino."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963465","ankiGuid":"fSvSd&T(`|"},{"id":"anki-ginecologia-cancer-de-colo-uterino-f88aeb58f3b9cd96","number":"0294r","sourceNumber":"0294r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Paciente de 43 anos de idade apresenta carcinoma espinocelular do colo do útero, estadio FIGO Ib. Foi realizada cirurgia de Wertheim-Meigs, com preservação dos ovários. O resultado anatomopatológico da peça mostrou margens vaginais livres, linfonodos negativos e infiltração dos paramétrios laterais por neoplasia, porém com margens cirúrgicas livres de neoplasia. A conduta subsequente deve ser","options":{"A":"ooforectomia bilateral.","B":"quimioterapia adjuvante.","C":"radioterapia pélvica.","D":"exenteração pélvica anterior.","E":"seguimento clínico mensal com citologia e colposcopia."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963466","ankiGuid":"PjuJ`aicj!"},{"id":"anki-ginecologia-cancer-de-colo-uterino-c935873544bdeab4","number":"0295r","sourceNumber":"0295r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Mulher de 48 anos, G4P40, chega ao pronto socorro com queixa de sangramento vaginal abundante há 4 horas. Ao exame clínico verifica-se PA= 90x40 mmHg, FC= 110 bpm, descorada ++\\4+. No exame especular observa-se a imagem representada na Figura, com sangramento ativo. Ao toque vaginal nota-se que a lesão infiltra os fórnices vaginais e ao toque retal nota-se infiltração bilateral dos paramétrios proximais ao colo uterino.\n\nQual a conduta inicial a ser associada à ressuscitação hemodinâmica?","options":{"A":"Embolização de artérias hipogástricas","B":"Cauterização elétrica","C":"Histerectomia de urgência","D":"Tamponamento vaginal"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":["question_bank/media/ginecologia-cancer-de-colo-uterino/paste-31888c1bdb9e75b89b9f0db057b848e99bd82fda.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963467","ankiGuid":"Pdgm&2X,R3"},{"id":"anki-ginecologia-cancer-de-colo-uterino-bcfeccb71bac3270","number":"0296r","sourceNumber":"0296r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Sobre o câncer do colo uterino, é correto afirmar que:","options":{"A":"as lesões precursoras demoram cerca de dois anos para progredir para câncer","B":"é considerado o mais frequente tipo de câncer entre as mulheres","C":"a maioria dos casos se desenvolve na zona de transformação","D":"o adenocarcinoma representa cerca de 90% dos casos"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963468","ankiGuid":"eWwLcH_j9@"},{"id":"anki-ginecologia-cancer-de-colo-uterino-aa22c07df5377a54","number":"0297r","sourceNumber":"0297r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Uma jovem de 22 anos vem à consulta queixando-se de sangramento pós-coital há 6 meses. Traz exame preventivo realizado há 30 dias com resultado de NIC III. O exame colposcópico mostra lesão acetobranca grosseira, no lábio anterior do colo, que foi biopsiada. Resultado do anátomo-patológico compatível com carcinoma in situ do colo uterino. A conduta indicada é:","options":{"A":"Repetir citopatológico em 30 dias.","B":"Realizar curetagem do canal cervical.","C":"Solicitar captura híbrida para pesquisa de HPV.","D":"Realizar conização do colo uterino."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963469","ankiGuid":"pYJB0lCMP1"},{"id":"anki-ginecologia-cancer-de-colo-uterino-b3dbbbea68d5ca9c","number":"0298r","sourceNumber":"0298r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Para o tratamento da obstrução ureteral, por doença neoplásica cervical extensa, a conduta imediata e mais indicada é:","options":{"A":"Radioterapia paliativa.","B":"Derivação da via urinária.","C":"Cirurgia pélvica radical e bolsa ileal.","D":"Quimioterapia com cisplatinum."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963470","ankiGuid":"jolvhexbH/"},{"id":"anki-ginecologia-cancer-de-colo-uterino-375a236e5c31ad53","number":"0299r","sourceNumber":"0299r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Um ginecologista recebe uma paciente com laudo histopatológico de carcinoma invasor de colo. Os exames necessários para o estadiamento desse tumor são:","options":{"A":"Toque vaginal, toque retal e, se paramétrios acometidos, cistoscopia e retossigmoidoscopia.","B":"Ultrassonografia transvaginal e, se paramétrios acometidos, cistoscopia e retossigmoidoscopia.","C":"Toque vaginal, toque retal e, se paramétrios acometidos, avaliação dos linfonodos por ressonância.","D":"Ultrassonografia transvaginal e, se paramétrios acometidos, avaliação dos linfonodos por ressonância."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963471","ankiGuid":"F]`k+|JX(i"},{"id":"anki-ginecologia-cancer-de-colo-uterino-717d01169ce3b0e8","number":"02100r","sourceNumber":"02100r","collectionBlock":"anki:ginecologia-cancer-de-colo-uterino","collectionLabel":"Anki · Câncer de Colo Uterino","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Câncer de Colo Uterino","subtopic":"","stem":"Com relação ao tratamento de pacientes com carcinoma de colo uterino, de acordo com seu estadio clínico (EC), não podemos afirmar que:","options":{"A":"no Estádio clínico IA1, deve-se realizar histerectomia total","B":"no Estádio clínico IA1, sem condições cirúrgicas, sugere-se radioterapia externa e/ou braquiterapia isolada.","C":"no Estádio clínico IA1, deve-se realizar a pesquisa do linfonodo sentinela (LNS) nos casos de invasão vascular.","D":"no Estádio clínico IA1, deve-se realizar histerectomia radical total com esvaziamento linfonodal, seguido de radioterapia externa e braquiterapia.","E":"no Estádio clínico IA1, deve-se realizar traquelectomia via vaginal ou conização, estes dois últimos em particular para pacientes que desejam preservar a fertilidade."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__02 - Ginecologia.apkg","sourceLabel":"Anki · Câncer de Colo Uterino","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Câncer de Colo Uterino","Anki"],"ankiNoteId":"1741794963472","ankiGuid":"pt)S<r(=cS"}]};
